#include <vector>

class Solution {
public:
    bool containsPattern(std::vector<int>& arr, int m, int k) {
        int count = 0, n = arr.size();
        for (int i = 0; i + m < n; ++i) {
            if (arr[i] == arr[i + m]) count++;
            else count = 0;
            if (count == (k - 1) * m) return true;
        }
        return false;
    }
};

class Solution {
    public boolean containsPattern(int[] arr, int m, int k) {
        int count = 0, n = arr.length;
        for (int i = 0; i + m < n; i++) {
            if (arr[i] == arr[i + m]) count++;
            else count = 0;
            if (count == (k - 1) * m) return true;
        }
        return false;
    }
}

